import { Router } from 'express';
import * as authCtrl from '../controllers/auth.controller.js';
import { authenticate, authLimiter, validate } from '../middleware/index.js';
import { loginSchema, changePasswordSchema } from '../validators/index.js';
const router = Router();
router.post('/login', authLimiter, validate({ body: loginSchema }), authCtrl.loginController);
router.post('/refresh-token', authCtrl.refreshTokenController);
router.post('/logout', authenticate, authCtrl.logoutController);
router.get('/me', authenticate, authCtrl.meController);
router.put('/change-password', authenticate, validate({ body: changePasswordSchema }), authCtrl.changePasswordController);
router.get('/sessions', authenticate, authCtrl.listSessionsController);
router.delete('/sessions/:sessionId', authenticate, authCtrl.revokeSessionController);
export default router;
